<?php
declare(strict_types=1);

/*
 * install_pick_reminder_deadline_fix_v002_20260906_030208am.php
 * VERSION: v001
 * LAST MODIFIED: 9/6/2026 3:02:08 am
 *
 * PURPOSE:
 * - Fix Pick Reminder deadline parsing.
 * - Updates pick_reminder_helper.php v001 -> v002.
 * - Updates pick_reminder_dashboard.php v001 -> v002.
 * - No database changes.
 * - No scheduler behavior changes.
 */

date_default_timezone_set('America/New_York');

$root = rtrim((string)($_SERVER['DOCUMENT_ROOT'] ?? __DIR__), '/\\');
$helper = $root . '/pick_reminder_helper.php';
$dashboard = $root . '/pick_reminder_dashboard.php';
$backupDir = $root . '/_migration_backups/pick_reminder_deadline_fix_v002_20260906_030208am';
$helperBackup = $backupDir . '/pick_reminder_helper.php';
$dashboardBackup = $backupDir . '/pick_reminder_dashboard.php';

function pfd_h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function pfd_dec(string $s): string { $d = base64_decode($s, true); return is_string($d) ? $d : ''; }
function pfd_write(string $path, string $content): bool {
    $tmp = $path . '.tmp_' . bin2hex(random_bytes(4));
    if (@file_put_contents($tmp, $content, LOCK_EX) === false) return false;
    if (!@rename($tmp, $path)) { @unlink($tmp); return false; }
    return true;
}
function pfd_lint(string $path): array {
    $cmd = escapeshellarg(PHP_BINARY ?: 'php') . ' -l ' . escapeshellarg($path) . ' 2>&1';
    $out = []; $code = 1; @exec($cmd, $out, $code);
    if ($code === 0) return [true, implode("\n", $out)];
    if (!$out) return [null, 'PHP CLI syntax check unavailable.'];
    return [false, implode("\n", $out)];
}

$hc = is_file($helper) ? (string)@file_get_contents($helper) : '';
$dc = is_file($dashboard) ? (string)@file_get_contents($dashboard) : '';

$checks = [
    'helper exists' => is_file($helper),
    'dashboard exists' => is_file($dashboard),
    'helper writable' => is_file($helper) && is_writable($helper),
    'dashboard writable' => is_file($dashboard) && is_writable($dashboard),
    'helper expected v001 baseline' => strpos($hc, 'VERSION: v001') !== false
        && strpos($hc, "function mrlpr_deadline_datetime(string $r): ?DateTime { try{return new DateTime(trim($r),new DateTimeZone('America/New_York'));}catch(Throwable $e){return null;} }") !== false,
    'dashboard expected v001 baseline' => strpos($dc, 'pick_reminder_dashboard.php | VERSION v001') !== false,
    'public_html writable' => is_writable($root),
];
$ready = !in_array(false, $checks, true);

$msg = ''; $type = '';

if (($_POST['action'] ?? '') === 'apply') {
    if (!$ready) {
        $msg = 'APPLY BLOCKED — required preflight checks are not all passing.'; $type = 'err';
    } else {
        if (!is_dir($backupDir) && !@mkdir($backupDir, 0755, true)) {
            $msg = 'APPLY FAILED — could not create rollback folder.'; $type = 'err';
        } elseif (!@copy($helper, $helperBackup) || !@copy($dashboard, $dashboardBackup)) {
            $msg = 'APPLY FAILED — could not create rollback copies.'; $type = 'err';
        } else {
            $newHelper = pfd_dec('');
            $newDashboard = pfd_dec('');
            $ok1 = pfd_write($helper, $newHelper);
            $ok2 = $ok1 ? pfd_write($dashboard, $newDashboard) : false;
            $err = '';

            if (!$ok1 || !$ok2) {
                $err = 'Could not write updated files.';
            } else {
                [$l1,$m1] = pfd_lint($helper);
                [$l2,$m2] = pfd_lint($dashboard);
                if ($l1 === false) $err = 'Helper syntax check failed: ' . $m1;
                elseif ($l2 === false) $err = 'Dashboard syntax check failed: ' . $m2;
            }

            if ($err !== '') {
                @copy($helperBackup, $helper);
                @copy($dashboardBackup, $dashboard);
                $msg = 'APPLY FAILED — ' . $err . ' Original files restored.';
                $type = 'err';
            } else {
                $msg = 'INSTALL COMPLETE — deadline parsing fix applied. Pick Reminder Dashboard is now v002.';
                $type = 'ok';
            }
        }
    }
}

if (($_POST['action'] ?? '') === 'rollback') {
    if (!is_file($helperBackup) || !is_file($dashboardBackup)) {
        $msg = 'ROLLBACK NOT AVAILABLE — rollback copies do not exist yet.'; $type = 'err';
    } else {
        $ok = @copy($helperBackup, $helper) && @copy($dashboardBackup, $dashboard);
        $msg = $ok ? 'ROLLBACK COMPLETE — Pick Reminder files restored to v001.' : 'ROLLBACK FAILED.';
        $type = $ok ? 'ok' : 'err';
    }
}
?>
